import numpy as np
from scipy.optimize import minimize

def f(x, y):
    return 3*x**2 + 3*y**2 - (x**2 * y**2) - 8*x*y - 1

def objective(a):
    # We want to maximize the minimum of f(a_i, a_j) for i < j
    # Or simply minimize -min(f(a_i, a_j))
    n = len(a)
    min_val = float('inf')
    for i in range(n):
        for j in range(i + 1, n):
            min_val = min(min_val, f(a[i], a[j]))
    return -min_val

def check_n(n):
    # Try several random starts
    for _ in range(20):
        # a_i must be positive and distinct
        # Let's pick values in (0, 5)
        a0 = np.random.uniform(0.1, 5.0, n)
        res = minimize(objective, a0, bounds=[(0.01, 10.0)] * n)
        if -res.fun >= 0:
            # Check if they are distinct
            if len(set(np.round(res.x, 6))) == n:
                return True, res.x
    return False, None

for n in range(2, 11):
    found, vals = check_n(n)
    print(f"n={n}: found={found}, vals={vals}")

